import os
import sys
import unittest

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
import json


class Tests(unittest.TestCase):
    def test_every_rate_is_a_number(self):
        rates = json.load(open(os.path.join(ROOT, "vendor", "rates.json")))["rates"]
        for code, rate in rates.items():
            self.assertIsInstance(rate, float, code)


if __name__ == "__main__":
    unittest.main()
